"""Storage backends for OAuth clients and tokens."""

import json
import os
import threading
import time
from abc import ABC, abstractmethod
from pathlib import Path
from typing import Optional

from .models import AccessToken, AuthorizationCode, RegisteredClient


class StorageBackend(ABC):
    """Abstract base class for OAuth storage backends."""

    # Client registration
    @abstractmethod
    def save_client(self, client: RegisteredClient) -> None:
        """Save a registered client."""
        pass

    @abstractmethod
    def get_client(self, client_id: str) -> Optional[RegisteredClient]:
        """Retrieve a client by ID."""
        pass

    @abstractmethod
    def delete_client(self, client_id: str) -> bool:
        """Delete a client. Returns True if deleted."""
        pass

    # Authorization codes
    @abstractmethod
    def save_authorization_code(self, auth_code: AuthorizationCode) -> None:
        """Save an authorization code."""
        pass

    @abstractmethod
    def get_authorization_code(self, code: str) -> Optional[AuthorizationCode]:
        """Retrieve and consume an authorization code."""
        pass

    # Access tokens
    @abstractmethod
    def save_access_token(self, token: [REDACTED] -> None:
        """Save an access token."""
        pass

    @abstractmethod
    def get_access_token(self, token: str) -> Optional[AccessToken]:
        """Retrieve an access token."""
        pass

    @abstractmethod
    def get_token_by_refresh_token(self, refresh_token: str) -> Optional[AccessToken]:
        """Retrieve an access token by its refresh token."""
        pass

    @abstractmethod
    def revoke_access_token(self, token: str) -> bool:
        """Revoke an access token. Returns True if revoked."""
        pass


class InMemoryStorage(StorageBackend):
    """In-memory storage backend. Data is lost on restart."""

    def __init__(self):
        self._clients: dict[str, RegisteredClient] = {}
        self._auth_codes: dict[str, AuthorizationCode] = {}
        self._access_tokens: dict[str, AccessToken] = {}
        self._refresh_tokens: dict[str, str] = {}  # refresh_token -> access_token
        self._lock = threading.Lock()

    def save_client(self, client: RegisteredClient) -> None:
        with self._lock:
            self._clients[client.client_id] = client

    def get_client(self, client_id: str) -> Optional[RegisteredClient]:
        with self._lock:
            return self._clients.get(client_id)

    def delete_client(self, client_id: str) -> bool:
        with self._lock:
            if client_id in self._clients:
                del self._clients[client_id]
                return True
            return False

    def save_authorization_code(self, auth_code: AuthorizationCode) -> None:
        with self._lock:
            self._auth_codes[auth_code.code] = auth_code

    def get_authorization_code(self, code: str) -> Optional[AuthorizationCode]:
        with self._lock:
            auth_code = self._auth_codes.pop(code, None)
            if auth_code and auth_code.expires_at > time.time():
                return auth_code
            return None

    def save_access_token(self, token: [REDACTED] -> None:
        with self._lock:
            self._access_tokens[token.token] = token
            if token.refresh_token:
                [REDACTED]] = token.token

    def get_access_token(self, token: str) -> Optional[AccessToken]:
        with self._lock:
            access_token = [REDACTED]
            if access_token and access_token.expires_at > time.time():
                return access_token
            return None

    def get_token_by_refresh_token(self, refresh_token: str) -> Optional[AccessToken]:
        with self._lock:
            token = [REDACTED]
            if token:
                return self._access_tokens.get(token)
            return None

    def revoke_access_token(self, token: str) -> bool:
        with self._lock:
            if token in self._access_tokens:
                access_token = [REDACTED]
                if access_token.refresh_token:
                    [REDACTED], None)
                return True
            return False


class FileStorage(StorageBackend):
    """File-based storage backend. Data persists across restarts."""

    def __init__(self, storage_dir: Optional[Path] = None):
        self._storage_dir = storage_dir or Path(
            os.environ.get(
                "OAUTH_STORAGE_DIR",
                Path.home() / ".config" / "google-calendar-mcp" / "oauth",
            )
        )
        self._storage_dir.mkdir(parents=True, exist_ok=True)
        self._clients_file = self._storage_dir / "clients.json"
        self._auth_codes_file = self._storage_dir / "auth_codes.json"
        self._tokens_file = self._storage_dir / "tokens.json"
        self._lock = threading.Lock()

    def _read_json(self, path: Path) -> dict:
        if path.exists():
            with open(path) as f:
                return json.load(f)
        return {}

    def _write_json(self, path: Path, data: dict) -> None:
        with open(path, "w") as f:
            json.dump(data, f, indent=2)

    def save_client(self, client: RegisteredClient) -> None:
        with self._lock:
            clients = self._read_json(self._clients_file)
            clients[client.client_id] = client.model_dump()
            self._write_json(self._clients_file, clients)

    def get_client(self, client_id: str) -> Optional[RegisteredClient]:
        with self._lock:
            clients = self._read_json(self._clients_file)
            if client_id in clients:
                return RegisteredClient(**clients[client_id])
            return None

    def delete_client(self, client_id: str) -> bool:
        with self._lock:
            clients = self._read_json(self._clients_file)
            if client_id in clients:
                del clients[client_id]
                self._write_json(self._clients_file, clients)
                return True
            return False

    def save_authorization_code(self, auth_code: AuthorizationCode) -> None:
        with self._lock:
            codes = self._read_json(self._auth_codes_file)
            codes[auth_code.code] = auth_code.model_dump()
            self._write_json(self._auth_codes_file, codes)

    def get_authorization_code(self, code: str) -> Optional[AuthorizationCode]:
        with self._lock:
            codes = self._read_json(self._auth_codes_file)
            if code in codes:
                auth_code = AuthorizationCode(**codes.pop(code))
                self._write_json(self._auth_codes_file, codes)
                if auth_code.expires_at > time.time():
                    return auth_code
            return None

    def save_access_token(self, token: [REDACTED] -> None:
        with self._lock:
            tokens = self._read_json(self._tokens_file)
            tokens[token.token] = token.model_dump()
            if token.refresh_token:
                tokens[f"refresh:{token.refresh_token}"] = token.token
            self._write_json(self._tokens_file, tokens)

    def get_access_token(self, token: str) -> Optional[AccessToken]:
        with self._lock:
            tokens = self._read_json(self._tokens_file)
            if token in tokens and isinstance(tokens[token], dict):
                access_token = [REDACTED]])
                if access_token.expires_at > time.time():
                    return access_token
            return None

    def get_token_by_refresh_token(self, refresh_token: str) -> Optional[AccessToken]:
        with self._lock:
            tokens = self._read_json(self._tokens_file)
            token = [REDACTED]"refresh:{refresh_token}")
            if token and token in tokens:
                return AccessToken(**tokens[token])
            return None

    def revoke_access_token(self, token: str) -> bool:
        with self._lock:
            tokens = self._read_json(self._tokens_file)
            if token in tokens and isinstance(tokens[token], dict):
                access_token = [REDACTED]
                if access_token.refresh_token:
                    [REDACTED]"refresh:{access_token.refresh_token}", None)
                self._write_json(self._tokens_file, tokens)
                return True
            return False

"""Gmail API service wrapper."""

import base64
from typing import Optional, Union

from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build

from .models import (
    GmailMessage,
    GmailProfile,
    GmailThread,
    ListMessagesResponse,
    MessageListItem,
)


class GmailService:
    """Service class for interacting with the Gmail API."""

    def __init__(self, credentials: Credentials):
        """Initialize with Google OAuth credentials.

        Args:
            credentials: Google OAuth2 credentials object
        """
        self._credentials = credentials
        self._service = None

    @property
    def service(self):
        """Get or create the Gmail API service."""
        if self._service is None:
            self._service = build("gmail", "v1", credentials=self._credentials)
        return self._service

    def get_profile(self) -> GmailProfile:
        """Get the Gmail profile of the authenticated user."""
        profile = self.service.users().getProfile(userId="me").execute()
        return GmailProfile(
            email_address=profile.get("emailAddress", ""),
            messages_total=profile.get("messagesTotal", 0),
            threads_total=profile.get("threadsTotal", 0),
            history_id=profile.get("historyId", ""),
        )

    def list_messages(
        self,
        q: Optional[str] = None,
        page_token: [REDACTED]] = None,
        max_results: int = 10,
    ) -> ListMessagesResponse:
        """List messages with optional search query."""
        params = {
            "userId": "me",
            "maxResults": max_results,
        }
        if q:
            params["q"] = q
        if page_token:
            params["pageToken"] = page_token

        response = self.service.users().messages().list(**params).execute()

        messages = []
        for msg_ref in response.get("messages", []):
            # Fetch basic message details for each message
            msg = self.service.users().messages().get(
                userId="me",
                id=msg_ref["id"],
                format="metadata",
                metadataHeaders=["Subject", "From", "To", "Date"],
            ).execute()

            headers = {h["name"]: h["value"] for h in msg.get("payload", {}).get("headers", [])}

            messages.append(
                MessageListItem(
                    id=msg["id"],
                    thread_id=msg["threadId"],
                    snippet=msg.get("snippet", ""),
                    subject=headers.get("Subject", ""),
                    **{"from": headers.get("From", "")},
                    to=headers.get("To", ""),
                    date=headers.get("Date", ""),
                )
            )

        return ListMessagesResponse(
            messages=messages,
            next_page_token=[REDACTED]"nextPageToken"),
            result_size_estimate=response.get("resultSizeEstimate", 0),
        )

    def get_message(self, message_id: str) -> GmailMessage:
        """Get a specific message by ID."""
        msg = self.service.users().messages().get(
            userId="me",
            id=message_id,
            format="full",
        ).execute()

        return self._parse_message(msg)

    def get_thread(self, thread_id: str, include_full_messages: bool = True) -> GmailThread:
        """Get a specific thread by ID."""
        thread = self.service.users().threads().get(
            userId="me",
            id=thread_id,
            format="full" if include_full_messages else "metadata",
        ).execute()

        messages = []
        for msg in thread.get("messages", []):
            messages.append(self._parse_message(msg))

        return GmailThread(
            id=thread["id"],
            snippet=thread.get("snippet", ""),
            messages=messages,
        )

    def _parse_message(self, msg: dict) -> GmailMessage:
        """Parse a raw Gmail API message into our model."""
        payload = msg.get("payload", {})
        headers = {h["name"]: h["value"] for h in payload.get("headers", [])}

        body_text = ""
        body_html = ""

        # Extract body from message parts
        if "body" in payload and payload["body"].get("data"):
            body_text = self._decode_body(payload["body"]["data"])
        elif "parts" in payload:
            body_text, body_html = self._extract_body_from_parts(payload["parts"])

        return GmailMessage(
            id=msg["id"],
            thread_id=msg["threadId"],
            label_ids=msg.get("labelIds", []),
            snippet=msg.get("snippet", ""),
            subject=headers.get("Subject", ""),
            **{"from": headers.get("From", "")},
            to=headers.get("To", ""),
            date=headers.get("Date", ""),
            body_text=body_text,
            body_html=body_html,
        )

    def _extract_body_from_parts(self, parts: list) -> tuple[str, str]:
        """Recursively extract text and HTML body from message parts."""
        text_body = ""
        html_body = ""

        for part in parts:
            mime_type = part.get("mimeType", "")
            body = part.get("body", {})

            if mime_type == "text/plain" and body.get("data"):
                text_body = self._decode_body(body["data"])
            elif mime_type == "text/html" and body.get("data"):
                html_body = self._decode_body(body["data"])
            elif "parts" in part:
                # Recursively handle nested parts
                nested_text, nested_html = self._extract_body_from_parts(part["parts"])
                if not text_body:
                    text_body = nested_text
                if not html_body:
                    html_body = nested_html

        return text_body, html_body

    def _decode_body(self, data: str) -> str:
        """Decode base64url encoded body data."""
        try:
            decoded = base64.urlsafe_b64decode(data.encode("ASCII"))
            return decoded.decode("utf-8", errors="replace")
        except Exception:
            return ""

    def list_labels(self) -> list[dict]:
        """List all labels in the user's mailbox."""
        response = self.service.users().labels().list(userId="me").execute()
        labels = []
        for label in response.get("labels", []):
            labels.append({
                "id": label.get("id", ""),
                "name": label.get("name", ""),
                "type": label.get("type", ""),  # system or user
            })
        return labels

    def get_label(self, label_id: str) -> dict:
        """Get details of a specific label."""
        label = self.service.users().labels().get(userId="me", id=label_id).execute()
        return {
            "id": label.get("id", ""),
            "name": label.get("name", ""),
            "type": label.get("type", ""),
            "messages_total": label.get("messagesTotal", 0),
            "messages_unread": label.get("messagesUnread", 0),
            "threads_total": label.get("threadsTotal", 0),
            "threads_unread": label.get("threadsUnread", 0),
        }

    def create_label(self, name: str, label_list_visibility: str = "labelShow", message_list_visibility: str = "show") -> dict:
        """Create a new label.

        Args:
            name: The display name of the label
            label_list_visibility: Show in label list - "labelShow", "labelShowIfUnread", or "labelHide"
            message_list_visibility: Show in message list - "show" or "hide"
        """
        label_body = {
            "name": name,
            "labelListVisibility": label_list_visibility,
            "messageListVisibility": message_list_visibility,
        }
        label = self.service.users().labels().create(userId="me", body=label_body).execute()
        return {
            "id": label.get("id", ""),
            "name": label.get("name", ""),
            "type": label.get("type", ""),
        }

    def modify_message_labels(
        self,
        message_id: str,
        add_label_ids: Optional[list[str]] = None,
        remove_label_ids: Optional[list[str]] = None,
    ) -> list[str]:
        """Modify labels on a message.

        Args:
            message_id: The ID of the message to modify
            add_label_ids: Label IDs to add to the message
            remove_label_ids: Label IDs to remove from the message

        Returns:
            The updated list of label IDs on the message
        """
        body = {}
        if add_label_ids:
            body["addLabelIds"] = add_label_ids
        if remove_label_ids:
            body["removeLabelIds"] = remove_label_ids

        result = self.service.users().messages().modify(
            userId="me",
            id=message_id,
            body=body,
        ).execute()

        return result.get("labelIds", [])

    def modify_thread_labels(
        self,
        thread_id: str,
        add_label_ids: Optional[list[str]] = None,
        remove_label_ids: Optional[list[str]] = None,
    ) -> str:
        """Modify labels on all messages in a thread.

        Args:
            thread_id: The ID of the thread to modify
            add_label_ids: Label IDs to add to all messages
            remove_label_ids: Label IDs to remove from all messages

        Returns:
            The thread ID
        """
        body = {}
        if add_label_ids:
            body["addLabelIds"] = add_label_ids
        if remove_label_ids:
            body["removeLabelIds"] = remove_label_ids

        result = self.service.users().threads().modify(
            userId="me",
            id=thread_id,
            body=body,
        ).execute()

        return result.get("id", "")
